select city, signup_cohort, avg_credit_limit from (select city, case when year(signup_date) < 2024 then 'before_2024' when year(signup_date) = 2024 then '2024' else 'after_2024' end as signup_cohort, round(avg(credit_limit), 2) as avg_credit_limit from customers where age between 57 and 67 group by city, case when year(signup_date) < 2024 then 'before_2024' when year(signup_date) = 2024 then '2024' else 'after_2024' end) as sub where avg_credit_limit > 73
